function downloadFinancialReportXlsx(report, formats) {
  const bytes = buildFinancialReportXlsxBytes(report, formats);
  const blob = new Blob([bytes], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
  return shareOrDownloadBlob(blob, financeExportFilename(report.period, "xlsx"), "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
}

// build the plain-text summary used by the Web Share API (with clipboard/alert fallback)
// v1.14.9 (i18n cleanup): `tr`/`trc` (t/tc) are OPTIONAL — omitting them renders the pre-existing Thai text unchanged. When given, the
// system-owned labels follow the selected UI language (counts are pluralised through tc); the group name and the already-formatted
// date string are passed through untouched.
function buildShareText({ name, date, playerCount, totalMatches, maxGames, totalExpense }, tr, trc) {
  if (!tr || !trc) return `BadQ — ${name || "ก๊วนแบดมินตัน"}\n${date || ""}\nผู้เล่น ${playerCount} คน\n${totalMatches} แมตช์\nเกมมากสุด ${maxGames} เกม\nค่าใช้จ่ายรวม ${formatCurrency(totalExpense)}`;
  return [`BadQ — ${name || tr("share.groupSummary.defaultName")}`, date || "", trc("share.playersLine", playerCount), trc("common.matchCount", totalMatches), tr("share.mostGamesLine", { count: maxGames }), tr("share.totalExpenseLine", { amount: formatCurrency(totalExpense) })].join("\n");
}
// v1.11.4: single Tournament share-text generator — built from the SAME buildTournamentResultReport
// object that feeds the Podium/Bracket/PDF, so the shared text can never separately calculate or drift
// from what's actually on screen. Includes medals + the final score line; ends with a small BadQ credit.
// v1.12.54 (Localization fix, Item 2 — verified defect): this generates system-owned text (medal
// labels, status, credit line — never user-entered names) handed to the OS share sheet/clipboard, and
// previously had no `tr` parameter at all, so it never followed the selected UI language. `tr` is
// OPTIONAL (both call sites already pass it) — omitting it still renders the exact pre-fix Thai text,
// so no existing behavior changes for a caller that doesn't thread it. Every reused key below is an exact
// text match for the string it replaces (tournament.unnamedFallback/teams/active/champion/runnerUp,
// tournamentWizard.thirdPlaceLabel, summary.matchesLabel); the two with no existing match
// (the in-progress status line and the credit line) get new keys instead of reusing a near-miss.
function buildTournamentShareText(report, teamsById, peopleById, formatDate = fmtThaiDate, tr) {
  const L = (key, fallback) => (tr ? tr(key) : fallback);
  const { t, totals, podium, finalMatch, isCompleted } = report;
  const lines = [`🏆 BadQ Tournament — ${t.name || L("tournament.unnamedFallback", "Tournament ไม่มีชื่อ")}`, `${formatDate(t.date)} · ${totals.teamCount} ${L("tournament.teams", "ทีม")} · ${totals.completedMatches} ${L("summary.matchesLabel", "แมตช์")}`];
  if (podium && podium.champion) {
    lines.push("");
    lines.push(`🥇 ${L("tournament.champion", "แชมป์")}: ${tTeamName(teamsById[podium.champion], peopleById)}`);
    if (podium.runnerUp) lines.push(`🥈 ${L("tournament.runnerUp", "รองแชมป์")}: ${tTeamName(teamsById[podium.runnerUp], peopleById)}`);
    if (podium.thirdIds && podium.thirdIds.length) lines.push(`🥉 ${L("tournamentWizard.thirdPlaceLabel", "อันดับ 3")}: ${podium.thirdIds.map((id) => tTeamName(teamsById[id], peopleById)).join(" / ")}`);
    if (finalMatch && matchScoreText(finalMatch)) {
      const lbl = tMatchLabel(finalMatch, teamsById, peopleById);
      lines.push(`${L("tournament.shareFinalLabel", "ชิงชนะเลิศ")}: ${lbl.a} ${matchScoreText(finalMatch)} ${lbl.b}`);
    }
  } else if (!isCompleted) {
    lines.push("");
    lines.push(L("tournament.shareStatusInProgress", "สถานะ: กำลังแข่งขัน — ยังไม่ทราบผู้ชนะ"));
  }
  lines.push("");
  lines.push(L("tournament.shareCredit", "สร้างโดย BadQ 🏸"));
  return lines.join("\n");
}
async function shareSummary(text, tr) {
  try {
    if (navigator.share) { await navigator.share({ text }); return; }
  } catch (e) { return; }
  try { await navigator.clipboard.writeText(text); alert(tr ? tr("share.copiedFallback") : "อุปกรณ์นี้แชร์ตรงไม่ได้ — คัดลอกข้อความสรุปก๊วนแล้ว"); }
  catch (e) { alert(text); }
}
// read an image WITHOUT cropping (for QR — must stay scannable)
function fileToDataURL(file) {
  return new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => rej(new Error("read")); r.readAsDataURL(file); });
}
function loadImg(src) {
  return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error("img")); i.src = src; });
}
// QR: keep full (no crop). Downscale if possible, else use raw data URL so it always shows.
async function readImageFull(file) {
  let dataUrl;
  try { dataUrl = await fileToDataURL(file); } catch (e) { return null; }
  try {
    const img = await loadImg(dataUrl);
    const max = 720; const sc = Math.min(1, max / Math.max(img.width, img.height));
    const w = Math.max(1, Math.round(img.width * sc)), h = Math.max(1, Math.round(img.height * sc));
    const cv = document.createElement("canvas"); cv.width = w; cv.height = h;
    cv.getContext("2d").drawImage(img, 0, 0, w, h);
    return cv.toDataURL("image/jpeg", 0.92);
  } catch (e) { return dataUrl; }
}
// v1.12.44 (Localization Closure): `t` is OPTIONAL — pass it from a caller that already has i18n threaded
// (GroupSessionHeader, SessionTab's compact context line) and the exact pre-v1.12.44 Thai renders unchanged;
// omit it (existing callers this phase doesn't touch, e.g. HistoricalDetail) and it also renders unchanged.
function fmtMode(settings, mode, t) {
  const modeWord = t ? t(mode === "doubles" ? "quanSettings.doublesShort" : "quanSettings.singlesShort") : (mode === "doubles" ? "ตีคู่" : "ตีเดี่ยว");
  const points = t ? t("score.pointsSuffix", { score: settings.winScore || 21 }) : `${settings.winScore || 21} แต้ม`;
  const deuceWord = t ? t(settings.deuce ? "score.deuceOn" : "score.deuceOff") : (settings.deuce ? "มีดิว" : "ไม่มีดิว");
  return `🏸 ${modeWord} · ${points} · ${deuceWord} · ${roundsLabel(settings.rounds, t)}`;
}
// one-line summary shown on the Today tab's "⚙️ ตั้งค่าก๊วน" entry point — reflects the real current
// session config so organizers don't have to open the sheet just to check it.
// v1.12.44 (Localization Closure): `t`/`tc` optional, same convention as fmtMode/roundsLabel above. levelLabel
// (from getPresetMeta) is untouched here — level preset names belong to LevelPresetEditor/CustomLevelEditor,
// out of this phase's scope (see the coverage report).
function quanSettingsSummary(settings, mode, courtCount, t, tc) {
  const modeLabel = mode === "singles" ? "1v1" : "2v2";
  const levelLabel = presetDisplayName(settings.levelPresetId || "badweb-central", t);
  const courtWord = tc ? tc("common.courtCount", courtCount) : `${courtCount} สนาม`;
  const points = t ? t("score.pointsSuffix", { score: settings.winScore || 21 }) : `${settings.winScore || 21} แต้ม`;
  return `${modeLabel} · ${courtWord} · ${points} · ${levelLabel}`;
}
// dynamic subtitle for the "💵 การชำระเงินและต้นทุน" compact entry point on the ชำระเงิน tab
const COST_MODEL_LABEL = { splitExpenses: "หารค่าใช้จ่าย", simple: "แบบง่าย", perCourt: "แยกรายสนาม", hourly: "รายชั่วโมง", perPerson: "รายคน", custom: "กำหนดเอง" };
function financeSettingsSummary(settings, t) {
  const model = settings.costModel || "simple";
  const parts = model === "simple"
    ? [
        t ? t("finance.simpleCourtFeeSummary", { amount: formatCurrency(settings.court || 0) }) : `ค่าสนาม ${formatCurrency(settings.court || 0)}/คน`,
        t ? t("finance.simpleShuttleFeeSummary", { amount: formatCurrency(settings.shuttle || 0) }) : `ค่าลูก ${formatCurrency(settings.shuttle || 0)}/เกม`,
      ]
    : [t ? `${t("finance.costModelLabel")}: ${t(`finance.chargeMode.${model === "splitExpenses" ? "split" : model}`)}` : `รูปแบบ: ${COST_MODEL_LABEL[model] || model}`];
  if (settings.other) parts.push(`${t ? t("common.miscellaneous") : "อื่นๆ"} ${formatCurrency(settings.other)}`);
  // v1.12.1 (UX restructure, spec 7): Reward moved out of this card entirely (now in Advanced Settings),
  // so its "รางวัลเปิด/ไม่มีรางวัล" segment no longer belongs in this summary — do not re-add it here.
  return parts.join(" · ");
}
// FAIRNESS SCORING (v1.9.4) — combines real elapsed wait time with games-played into one weighted
// priority number, instead of the old strict lexicographic sort (lastPlayedRound tier, then games tier,
// then waitingSince tier) which let "games played" fully dominate even when a rival had waited far
// longer within the same games-tier. Higher score = should play sooner. Derived entirely from existing
// player fields (waitingSince/games/lastPlayedRound) — no new duplicated counters (see IMPLEMENTATION
// PRINCIPLE). Weights: 1 minute of extra real wait is worth a bit less than a whole game not yet played,
// so a long-waiting player can still outrank someone who's only played slightly fewer games, while a
// player who just finished (waitingSince resets to "now" the instant a match starts/ends) naturally drops
// to the bottom of the queue even if their games count is low — satisfying "avoid picking the same player
// for too many consecutive games when other suitable waiting players exist" without extra bookkeeping.
function fairnessScore(p, now) {
  const waitMin = Math.max(0, (now - (p.waitingSince || now)) / 60000);
  return waitMin - (p.games || 0) * 1.5;
}
// selection priority: fairness score (wait time + games played, weighted) first, lastPlayedRound/order as
// tiebreaks. Downstream, buildMatch() still takes the top of THIS ordering as a shortlist and picks the
// best-BALANCED valid combination from within it — fairness decides WHO is eligible/likely to play next,
// balance decides HOW they're paired, exactly as requirement 1 asks ("prioritize fairness, but the final
// 4-player combination should still be reasonably balanced").
// v1.11.34: Owner matchmaking priority (spec: "Owner ควรถูกเลือกเป็นคนสุดท้าย"). Owners sort strictly after
// every non-Owner ready player (fairness/lastPlayedRound/order still decide the order WITHIN each group,
// completely unchanged) — this is what pushes them out of buildMatch's shortlist window while enough
// non-Owner players remain, without touching a single other priority rule. See OWNER_PENALTY in
// buildMatch below for the second half: even once an Owner IS in the shortlist, buildMatch still prefers
// any combination that avoids them, for as long as a valid one exists.
const SORT = (a, b) => {
  const now = Date.now();
  const aOwner = a.memberType === "owner" ? 1 : 0, bOwner = b.memberType === "owner" ? 1 : 0;
  if (aOwner !== bOwner) return aOwner - bOwner;
  return fairnessScore(b, now) - fairnessScore(a, now) || (a.lastPlayedRound ?? -1) - (b.lastPlayedRound ?? -1) || a.order - b.order;
};
// v1.11.65: split out from matchScoreText so the "ผล" column (SessionTab's MatchRow) can render one set
// per line instead of a single " · "-joined string — matchScoreText itself (used everywhere else: player
// history, Tournament cards/bracket, waitlist buttons) is unchanged, same per-set formatting, still
// returns the joined string.
function matchScoreParts(m) {
  if (!hasScore(m)) return null;
  return m.scores.filter((r) => r && (r.a != null || r.b != null || r.win != null)).map((r) => {
    if (r.a != null || r.b != null) return `${r.a ?? "-"}–${r.b ?? "-"}`;
    return r.win === "A" ? "A ชนะ" : r.win === "B" ? "B ชนะ" : "-";
  });
}
function matchScoreText(m) {
  const parts = matchScoreParts(m);
  return parts ? parts.join(" · ") : null;
}

async function resizePhoto(file) {
  let dataUrl;
  try { dataUrl = await fileToDataURL(file); } catch (e) { return null; }
  try {
    const img = await loadImg(dataUrl);
    const s = 180, cv = document.createElement("canvas");
    cv.width = s; cv.height = s;
    const ctx = cv.getContext("2d");
    const sc = Math.max(s / img.width, s / img.height);
    const w = img.width * sc, h = img.height * sc;
    ctx.drawImage(img, (s - w) / 2, (s - h) / 2, w, h);
    return cv.toDataURL("image/jpeg", 0.8);
  } catch (e) { return dataUrl; }
}

// v1.11.74 — samples the drawn canvas for any real translucent pixel (alpha < 255). Used by ImageCropper's
// confirm() to decide PNG (preserve transparency) vs JPEG (smaller file, no alpha needed) on a per-upload
// basis, instead of always flattening to JPEG. A stride > 1 would speed this up on very large canvases, but
// at the app's fixed 640x640 crop output a full scan is cheap (~400k pixels, runs in a few ms) and a full
// scan is the only way to guarantee a single translucent corner pixel of a logo/emblem isn't missed.
function canvasHasTransparency(ctx, w, h) {
  try {
    const data = ctx.getImageData(0, 0, w, h).data;
    for (let i = 3; i < data.length; i += 4) { if (data[i] < 255) return true; }
    return false;
  } catch (e) { return false; } // e.g. a tainted canvas from a cross-origin source — fall back to JPEG, never crash the upload
}
// v1.9.13: interactive "move & scale" crop step, shared by every photo-upload flow (player profile photo,
// ก๊วน photo, QR code) — lets the organizer drag to pan and pinch/slide to zoom a fixed square frame over
// the picked image before it's saved, instead of always auto-centering. Always exports a SQUARE image (the
// existing Avatar component already applies its own border-radius for circular display, so no shape-specific
// output is needed) — circleGuide only changes the on-screen preview mask, not the underlying crop math or
// the exported result. Pure presentation/input step: does not touch how/where the result is ultimately saved
// (each caller's onConfirm decides that, exactly as before this existed).
// v1.11.74: exports PNG instead of JPEG when the cropped result actually contains transparency (see
// canvasHasTransparency + confirm() below) — preserves real alpha for uploaded Rank/Group/Tournament PNG
// artwork instead of flattening it onto black. Ordinary opaque photos are unaffected (still JPEG).
function ImageCropper({ src, circleGuide, title, onCancel, onConfirm, maxSize }) {
  const FRAME = 300;
  const MAX_ZOOM = 4;
  const [natSize, setNatSize] = useState(null); // { w, h } once the picked image has loaded
  const [baseScale, setBaseScale] = useState(1); // scale at which the image just covers the frame (zoom=1)
  const [zoom, setZoom] = useState(1); // multiplier on top of baseScale, 1..MAX_ZOOM
  const [offset, setOffset] = useState({ x: 0, y: 0 }); // top-left of the displayed image, relative to the frame
  const imgElRef = useRef(null); // the actual loaded Image object, used for the final canvas draw
  const dragRef = useRef(null); // { sx, sy, ox, oy } while a mouse/single-touch drag is active
  const pinchRef = useRef(null); // { startDist, startZoom } while a two-finger pinch is active

  useEffect(() => {
    let cancelled = false;
    const img = new Image();
    img.onload = () => {
      if (cancelled) return;
      const w = img.naturalWidth || 1, h = img.naturalHeight || 1;
      const bs = FRAME / Math.min(w, h);
      setNatSize({ w, h });
      setBaseScale(bs);
      setZoom(1);
      setOffset({ x: (FRAME - w * bs) / 2, y: (FRAME - h * bs) / 2 });
    };
    img.src = src;
    imgElRef.current = img;
    return () => { cancelled = true; };
  }, [src]);

  const scale = baseScale * zoom;
  const dispW = natSize ? natSize.w * scale : 0;
  const dispH = natSize ? natSize.h * scale : 0;
  const clampOffset = (off, dw, dh) => {
    const minX = Math.min(0, FRAME - dw), minY = Math.min(0, FRAME - dh);
    return { x: Math.min(0, Math.max(minX, off.x)), y: Math.min(0, Math.max(minY, off.y)) };
  };
  const setZoomClamped = (z) => {
    if (!natSize) return;
    const nz = Math.min(MAX_ZOOM, Math.max(1, z));
    const ndw = natSize.w * baseScale * nz, ndh = natSize.h * baseScale * nz;
    setZoom(nz);
    setOffset((o) => clampOffset(o, ndw, ndh));
  };

  const onMouseDown = (e) => { dragRef.current = { sx: e.clientX, sy: e.clientY, ox: offset.x, oy: offset.y }; };
  const onMouseMove = (e) => {
    if (!dragRef.current) return;
    const dx = e.clientX - dragRef.current.sx, dy = e.clientY - dragRef.current.sy;
    setOffset(clampOffset({ x: dragRef.current.ox + dx, y: dragRef.current.oy + dy }, dispW, dispH));
  };
  const onMouseUp = () => { dragRef.current = null; };

  const touchDist = (t) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
  const onTouchStart = (e) => {
    if (e.touches.length === 1) { dragRef.current = { sx: e.touches[0].clientX, sy: e.touches[0].clientY, ox: offset.x, oy: offset.y }; pinchRef.current = null; }
    else if (e.touches.length === 2) { pinchRef.current = { startDist: touchDist(e.touches), startZoom: zoom }; dragRef.current = null; }
  };
  const onTouchMove = (e) => {
    e.preventDefault();
    if (e.touches.length === 1 && dragRef.current) {
      const dx = e.touches[0].clientX - dragRef.current.sx, dy = e.touches[0].clientY - dragRef.current.sy;
      setOffset(clampOffset({ x: dragRef.current.ox + dx, y: dragRef.current.oy + dy }, dispW, dispH));
    } else if (e.touches.length === 2 && pinchRef.current) {
      setZoomClamped(pinchRef.current.startZoom * (touchDist(e.touches) / pinchRef.current.startDist));
    }
  };
  const onTouchEnd = (e) => { if (e.touches.length === 0) { dragRef.current = null; pinchRef.current = null; } };

  const confirm = () => {
    if (!natSize || !imgElRef.current) return;
    // v1.12.20 (Image Storage & Reference Architecture, spec: "resize/compress BEFORE upload, do not
    // store full-size originals"): output size is now parameterized per image type instead of one fixed
    // 640×640 for everything — Player/Custom-Rank 256, Group/Tournament 512, per the spec's targets.
    // Any caller that doesn't pass maxSize keeps today's exact 640 behavior (backward compatible).
    const OUT = Number(maxSize) > 0 ? Number(maxSize) : 640;
    const sx = -offset.x / scale, sy = -offset.y / scale, sw = FRAME / scale, sh = FRAME / scale;
    const cv = document.createElement("canvas"); cv.width = OUT; cv.height = OUT;
    const ctx = cv.getContext("2d");
    ctx.drawImage(imgElRef.current, sx, sy, sw, sh, 0, 0, OUT, OUT);
    // v1.11.74 — root cause of the black-background bug: this shared crop step (player photo, ก๊วน/Group
    // photo, Rank tier image, Tournament logo — every upload flow funnels through here) used to ALWAYS
    // export via toDataURL("image/jpeg", ...). JPEG has no alpha channel, so any transparent source pixel
    // (e.g. a transparent PNG rank emblem or group logo) got silently flattened onto solid black — the
    // canvas's own default fill for a translucent pixel once it's forced into a non-alpha format. Ordinary
    // opaque photos never hit this path (fully opaque canvas -> no visual difference either way), so the
    // fix only needs to change format when real transparency is actually present, keeping JPEG's smaller
    // file size for the common case. See canvasHasTransparency below.
    const hasAlpha = canvasHasTransparency(ctx, OUT, OUT);
    onConfirm(hasAlpha ? cv.toDataURL("image/png") : cv.toDataURL("image/jpeg", 0.88));
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "#000", zIndex: 90, display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "14px 16px", paddingTop: "calc(14px + env(safe-area-inset-top))" }}>
        <button onClick={onCancel} style={{ width: 34, height: 34, borderRadius: 17, background: "rgba(255,255,255,0.15)", border: "none", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}><X size={18} /></button>
        <span style={{ color: "#fff", fontSize: 14, fontWeight: 700 }}>{title || "จัดตำแหน่งรูป"}</span>
        <button onClick={confirm} style={{ width: 34, height: 34, borderRadius: 17, background: T.accent, border: "none", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}><Check size={18} /></button>
      </div>
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", minHeight: 0 }}>
        <div
          onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
          onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}
          style={{ position: "relative", width: FRAME, height: FRAME, overflow: "hidden", borderRadius: circleGuide ? "50%" : 14, touchAction: "none", background: "#151515", cursor: "grab", boxShadow: "0 0 0 2000px rgba(0,0,0,0.55)" }}
        >
          {natSize && (
            <img src={src} draggable={false} alt="" style={{ position: "absolute", left: offset.x, top: offset.y, width: dispW, height: dispH, maxWidth: "none", userSelect: "none", pointerEvents: "none" }} />
          )}
        </div>
      </div>
      <div style={{ padding: "10px 24px calc(20px + env(safe-area-inset-bottom))", display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ fontSize: 13 }}>🔍</span>
        <input type="range" min={1} max={MAX_ZOOM} step={0.01} value={zoom} onChange={(e) => setZoomClamped(Number(e.target.value))} style={{ flex: 1 }} disabled={!natSize} />
      </div>
      <div style={{ textAlign: "center", color: "rgba(255,255,255,0.55)", fontSize: 11, paddingBottom: 10 }}>ลากเพื่อเลื่อน · บีบนิ้ว/เลื่อนแถบเพื่อซูม</div>
    </div>
  );
}

// fresh defaults for `settings` — pulled out into a function (instead of an inline useState() object
// literal) so the exact same shape can be reused both on first load AND as the fallback base when
// migrating an old/partial backup file on import. Called fresh each time so nobody accidentally shares
// (and mutates) the same wheelPrizes array reference.
function getDefaultSettings() {
  return {
    // v1.12.51 (Promotion & Loyalty Foundation): GROUP-SPECIFIC campaign storage, additive inside this same
    // existing `settings` object per spec section 1 — travels for free through the existing Group Default
    // (groupDefaults[session.name]), Backup/Restore, and boot-load plumbing, exactly like every other
    // settings field here. Brand-new/never-upgraded groups default to [] — no group suddenly gets an active
    // promotion after upgrading. See normSettings() for the normalization of a loaded/restored value.
    promotions: [],
    // v1.11.32: default pairingMode changed auto -> manual (explicit request) — only affects BRAND NEW
    // quans/settings built from scratch here; existing saved settings (which already have a stored
    // pairingMode, "auto" or "manual") are untouched, and every `settings.pairingMode === "manual"` check
    // elsewhere in the app is unchanged, so legacy data keeps behaving exactly as before.
    court: 65, shuttle: 25, other: 0, rounds: 1, winScore: 21, deuce: true, qr: null, bank: "", pairingMode: "manual",
    // v1.14.5: "ใช้เวลาจริงในการเปิด–ปิดสนาม". Default OFF so every existing group/session keeps today's behaviour.
    realtimeCourtAvailability: false,
    // v1.12.7 (fix 2): brand-new groups/settings now default to "badweb-central" (Bad Web / กลาง) instead of
    // "isan" — this ONLY affects settings objects built fresh from scratch here (new group, first install).
    // An existing group's already-saved levelPresetId (isan/north/badweb-central/custom) is loaded from its
    // own stored settings and never passes through this function, so it is never migrated/overwritten.
    levelPresetId: "badweb-central",
    customLevels: [],
    // ===== FLEXIBLE COST MODEL (v1.9.4) — "รูปแบบคิดค่าใช้จ่าย" =====
    // "simple" is the untouched original ค่าคอร์ท/ค่าลูก/ค่าใช้จ่ายอื่น model above (default — zero behavior
    // change for existing groups). The other 4 modes are OPTIONAL alternates the organizer opts into; see
    // computeCostModelExpenses() for how each one feeds the existing รายรับ/ค่าใช้จ่าย/กำไรสุทธิ pipeline.
    costModel: "simple", // "splitExpenses" | "simple" | "perCourt" | "hourly" | "perPerson" | "custom"
    perCourtRates: [], // [{ court: 1, amount: 500 }, ...] — model B: แยกรายสนาม
    hourly: { courts: 0, rate: 0, hours: 0 }, // model C: รายชั่วโมง (จำนวนสนาม × ราคา/ชั่วโมง × ชั่วโมง)
    shuttleCalc: { qty: 0, pricePerUnit: 0 }, // optional shared ค่าลูกแบด line, usable alongside perCourt/hourly
    // v1.11.41: ต้นทุน/ราคาขายลูกแบดต่อลูก — derives costPerShuttlecock = costPerTube / shuttlesPerTube and
    // auto-computes expense/revenue/profit from the EXISTING authoritative "used" count (session.stats.totalMatches
    // at endSession(), never a new manual field). Independent of costModel (unlike shuttleCalc above, which only
    // applies to perCourt/hourly) — when configured (costPerTube>0 && shuttlesPerTube>0) it SUPERSEDES the legacy
    // shuttleCalc auto-expense-line so the two can never both file a "ค่าลูกแบต" expense for the same session (see
    // computeCostModelExpenses). Kept fully separate from `shuttle` (the flat ฿/game charge billed to players,
    // frozen into each session's bill/sessionRevenue) by explicit organizer decision — no automatic interaction.
    // v1.11.50 (Financial Setup Enhancement, spec B): `sellingPricePerShuttle` is no longer editable in the
    // UI and no longer contributes to any NEW session's revenue (see endSession() — shuttlecockRevenue is
    // now always 0 going forward) because "ค่าลูก/เกม" (settings.shuttle, revenue side) already covers that
    // concept — a second "selling price per shuttle" was a duplicate concept per organizer request. The
    // field itself stays in the settings shape (never deleted/force-zeroed here) purely so an OLD backup
    // that still carries a nonzero value continues to load without error (Section L: no destructive migration).
    // v1.11.52 (Shuttlecock Cost Redesign, spec A): `purchaseRows` is the new source of truth — a real
    // purchase-record list (ยี่ห้อ/ราคาต่อหลอด/จำนวนหลอด/จำนวนลูกต่อหลอด). `costPerTube`/`shuttlesPerTube`
    // stay in the shape untouched (never deleted/force-zeroed) purely so an OLD backup that predates this
    // feature keeps loading without error (Section L) — see shuttlePurchaseRowsFor()'s legacy fallback.
    shuttleEco: { costPerTube: 0, shuttlesPerTube: 0, sellingPricePerShuttle: 0, purchaseRows: [] },
    // v1.11.50 (Financial Setup Enhancement, spec C/D): ต้นทุนก๊วน — new, independent-of-costModel cost
    // fields, same "always shown, supersedes the model-derived auto expense line" pattern as shuttleEco
    // above. courtCost.manualOverrideTotal: null = auto-calculate from courtCount × session duration ×
    // ratePerHour; a number = organizer's explicit override (เหมาจ่าย/โปรโมชั่น/ราคาจริงต่างจากปกติ), which
    // auto-calculation must never silently clobber (see computeCourtCostFinance).
    courtCost: { ratePerHour: 0, manualOverrideTotal: null },
    // v1.11.50 (Financial Setup Enhancement, spec E): free-form "ค่าใช้จ่ายอื่น ๆ" list — [{id, name, amount}]
    // — the organizer's own miscellaneous real costs (น้ำดื่ม/ค่าจอดรถ/อุปกรณ์ ฯลฯ), filed automatically as
    // "ค่าใช้จ่ายอื่น" expense line(s) at endSession(), same pipeline as every other auto expense line.
    otherExpenses: [],
    perPersonRate: 0, // model D: รายคน — overrides computeBill's per-person court charge directly (revenue-side)
    customCostRows: [], // model E: กำหนดเอง — [{ id, category, description, amount }, ...], reuses ExpenseListEditor
    // v1.11.12: model F (first in the picker) — หารค่าใช้จ่าย: organizer enters the 4 real cost lines below,
    // app auto-splits by ผู้เล่นที่มาจริง (see computeSplitExpenseSummary) instead of a manually-set rate.
    splitExpenses: { court: 0, shuttle: 0, water: 0, other: 0 },
    roundingMode: "none", // "none" | "round5" | "round10" — how the per-person charge from splitExpenses is rounded
    // v1.12.1 (UX restructure — Advanced Feature toggles): Reward defaults OFF for a brand-new settings
    // object (was `true`, duplicated by mistake — this also fixes that dead duplicate key). This ONLY
    // affects genuinely new/empty settings; an existing user's persisted `wheelEnabled` (or inferred value —
    // see applyPersistedState) always wins via the `{...getDefaultSettings(), ...base}` spread in
    // normSettings, so nobody who already uses Reward loses it.
    wheelEnabled: false,
    // v1.9.19: when true, prizes that have run out (qty 0) still appear on the wheel — grayed out, purely
    // visual, never actually landable — instead of disappearing. Default false = unchanged prior behavior
    // (sold-out prizes simply vanish from the wheel).
    wheelShowSoldOut: false,
    // v1.11.34: REDESIGNED reward model (spec section 6) — probability/value/wheelOrder are now
    // independent fields, never derived from qty or player count (see normWheelPrizes/pickWheelOutcome).
    // No "none" (ไม่ได้รางวัล) entry any more — "no prize" is always the automatic remainder
    // (100 - sum of active probabilities), never a real editable row.
    wheelPrizes: [
      { id: uid(), label: "ส่วนลด 20฿ (ใช้ทันที)", type: "now", amount: 20, qty: 5, totalQty: 5, probability: 15, value: 0, wheelOrder: 0 },
      { id: uid(), label: "ส่วนลด 10฿ (ครั้งหน้า)", type: "next", amount: 10, qty: 5, totalQty: 5, probability: 15, value: 0, wheelOrder: 1 },
      { id: uid(), label: "ฟรีค่าสนาม! ส่วนลด 65฿ (ทันที)", type: "now", amount: 65, qty: 2, totalQty: 2, probability: 5, value: 0, wheelOrder: 2 },
    ],
    lastBackupAt: null,
    // ===== COURT RECOMMENDATION ENGINE (v1.11.7, Part G; goal-based rewrite in v1.11.12) — configurable,
    // kept OFF the normal Group screen per spec (lives in a small settings sub-sheet reached from the
    // recommendation detail sheet).
    averageMatchMinutes: 15, // legacy per-MATCH default, kept only as a migration seed — no longer user-facing
    courtUtilization: 0.9, // internal warm-up/changeover buffer factor — never shown to the organizer as a %
    courtRecommendationMode: "balanced", // legacy "busy"/"balanced"/"saving" — no longer read by the calc engine, kept for old backups
    averageSetMinutes: 15, // v1.11.12: เวลาเฉลี่ยต่อ 1 เซต — the ONE user-facing time input; per-match time = this × expected sets from settings.rounds
    courtRecommendationGoal: "max_wait", // v1.11.12: "max_wait" (รอไม่เกิน X นาที) | "min_games" (เล่นอย่างน้อย X เกม/คน)
    maxWaitMinutes: 30,
    minGamesPerPerson: 4,
    // v1.11.73: เวลารอเป้าหมาย — used ONLY by the "min_games" goal's joint games/wait balance (replaces that
    // goal's previous reuse of maxWaitMinutes, a setting that actually belongs to the OTHER goal). A
    // GROUP-specific preference (lives inside `settings` on purpose, same reasoning as membership above — it
    // rides the existing groupDefaults save/apply/auto-mirror + backup/restore/boot-load plumbing for free).
    targetWaitMinutes: 15,
    // v1.11.17: จำนวนผู้เล่น — null/0 = ไม่จำกัด. Once registered/ready headcount reaches this cap, any
    // NEW check-in goes to the Waiting List instead (see setStatus) until the organizer promotes someone.
    maxPlayers: null,
    // v1.11.34: "ไม่ได้มานานเกิน [N] เดือน" threshold used by the ผู้เล่น tab's "ไม่ได้มานาน" filter — never
    // auto-deletes anyone, purely changes who shows up under that filter. Default 6 per spec.
    inactiveMonths: 6,
    // v1.11.67: Membership Fee & Status (section B) — per-group config, lives inside `settings` on
    // purpose so it rides the EXISTING groupDefaults save/apply + backup/restore/boot-load plumbing for
    // free (see saveGroupDefault/applyGroupDefaultsFor/applyPersistedState) instead of a new parallel
    // storage path. Inlined literally (matching every other default sub-object in this function, e.g.
    // shuttleEco/courtCost above — NOT a reference to the separate DEFAULT_MEMBERSHIP_SETTINGS constant,
    // which exists purely as a safe fallback for getMembershipStatus/UI call sites when membershipSettings
    // is null/undefined at render time; keeping these independent avoids a cross-file-region dependency
    // that would break tools which extract getDefaultSettings() in isolation).
    membership: { entranceFee: { enabled: false, amount: 0 }, recurring: { enabled: false, monthlyFee: 0, annualFee: 0 }, expiryWarningDays: 7 },
    // v1.12.1 (UX restructure — Advanced Feature toggles): Tournament defaults OFF for a brand-new settings
    // object, same reasoning/safety as wheelEnabled above — an existing user's persisted/inferred value
    // always wins (see applyPersistedState's inferredTournamentEnabled).
    tournamentEnabled: false,
  };
}
// v1.12.1: true when `prizes` is exactly the pristine 3-prize seed from getDefaultSettings() (ignoring the
// random `id` field) — used ONLY to detect "has this organizer ever actually customized Reward" for the
// one-time Reward-enabled migration inference below. Any length change or any field difference counts as
// customized; an absent/non-array value is treated as "not customized" (nothing to infer from).
function isDefaultWheelPrizes(prizes) {
  // v1.12.1 fix: an EMPTY array counts as "not yet configured" too, same as a completely absent field —
  // consistent with migrateBackupData's own pre-existing wheelPrizes backfill (`|| wheelPrizes.length === 0
  // -> use the default 3-item set`) a few lines below where this is used. Without this, an old/edge-case
  // blob that happens to carry `wheelPrizes: []` (rather than omitting the field) would be misread as "the
  // organizer deliberately emptied the wheel" and wrongly infer Reward as ON for a user who never touched it.
  if (!Array.isArray(prizes) || prizes.length === 0) return true;
  const def = getDefaultSettings().wheelPrizes;
  if (prizes.length !== def.length) return false;
  const sig = (p) => JSON.stringify({ label: p && p.label, type: p && p.type, amount: p && p.amount, qty: p && p.qty, totalQty: p && p.totalQty, probability: p && p.probability, value: p && p.value, wheelOrder: p && p.wheelOrder });
  return prizes.every((p, i) => sig(p) === sig(def[i]));
}
// v1.12.1 (UX restructure — Advanced Feature migration): shared by BOTH normal boot (applyPersistedState)
// AND backup restore (applyRestore's "replace" mode) so the two loading paths can never disagree on
// whether Tournament/Reward should come back enabled. Once `rawSettings.tournamentEnabled`/`wheelEnabled`
// is an explicit boolean, that stored choice always wins (never re-inferred, never auto-turned back on
// just because historical data still exists). Otherwise, infer ON only from genuine prior use so an
// existing user never silently loses a feature they were already using; a brand-new/empty settings object
// has no history to infer from and correctly stays OFF (new-user default).
function inferAdvancedFeatureFlags(rawSettings, rawActiveTournament, rawTournamentHistory, rawRewardHistory) {
  const rs = rawSettings || {};
  const tournamentEnabled = typeof rs.tournamentEnabled === "boolean"
    ? rs.tournamentEnabled
    : !!(normTournament(rawActiveTournament) || (Array.isArray(rawTournamentHistory) && rawTournamentHistory.length > 0));
  const wheelEnabled = typeof rs.wheelEnabled === "boolean"
    ? rs.wheelEnabled
    : !!((Array.isArray(rawRewardHistory) && rawRewardHistory.length > 0) || !isDefaultWheelPrizes(rs.wheelPrizes));
  return { tournamentEnabled, wheelEnabled };
}
// v1.11.7 (Part M) / v1.11.12: backward-compatible settings defaults — old saved settings objects predate
// these fields; backfill them without touching any existing customized value.
function normSettings(s) {
  const base = s && typeof s === "object" ? s : {};
  const amm = Number(base.averageMatchMinutes);
  const util = Number(base.courtUtilization);
  const asm = Number(base.averageSetMinutes);
  const mwm = Number(base.maxWaitMinutes);
  const mgp = Number(base.minGamesPerPerson);
  const twm = Number(base.targetWaitMinutes);
  const se = base.splitExpenses && typeof base.splitExpenses === "object" ? base.splitExpenses : {};
  // v1.11.41: old (pre-v1.11.41) saved settings have no `shuttleEco` at all — backfill field-by-field
  // (not just via the top-level {...getDefaultSettings(), ...base} spread above, which would keep a
  // partially-shaped object as-is instead of coercing/clamping each sub-field) so a corrupt/partial value
  // can never produce NaN/negative pricing downstream.
  const sEco = base.shuttleEco && typeof base.shuttleEco === "object" ? base.shuttleEco : {};
  // v1.11.52 (Shuttlecock Cost Redesign, spec A/J): materialize `purchaseRows` into a REAL, always-present
  // array so the new multi-row editor always has real editable state to render/update/delete. When the
  // stored value is already a genuine array (even an explicitly-emptied one — the organizer deleted every
  // row on purpose) it is trusted field-by-field; when the field is completely ABSENT (any pre-v1.11.52
  // backup) it is synthesized ONCE from the old flat costPerTube/shuttlesPerTube fields via the same
  // shuttlePurchaseRowsFor() fallback the calculation functions use, so the organizer sees their existing
  // config as a real, editable row instead of losing it. This is additive normalization, not destructive
  // migration — the old flat fields are still written back below untouched either way.
  const sEcoPurchaseRows = Array.isArray(sEco.purchaseRows)
    ? sEco.purchaseRows.filter((r) => r && typeof r === "object").map((r) => ({
        id: r.id || uid(),
        brand: String(r.brand || ""),
        costPerTube: Math.max(0, Number(r.costPerTube) || 0),
        tubes: Math.max(0, Number(r.tubes) || 0),
        shuttlesPerTube: Math.max(0, Number(r.shuttlesPerTube) || 0),
      }))
    : shuttlePurchaseRowsFor(sEco).map((r) => ({ ...r, id: uid() }));
  // v1.11.50: same field-by-field backfill discipline as shuttleEco above — a missing/partial/corrupt
  // courtCost or otherExpenses (any pre-v1.11.50 backup, or a hand-edited/corrupted import) must never
  // produce NaN/negative pricing or crash a later .map()/.reduce() over otherExpenses.
  const cCost = base.courtCost && typeof base.courtCost === "object" ? base.courtCost : {};
  const cCostOverrideNum = Number(cCost.manualOverrideTotal);
  const bMembership = base.membership && typeof base.membership === "object" ? base.membership : {};
  return {
    ...getDefaultSettings(),
    ...base,
    realtimeCourtAvailability: base.realtimeCourtAvailability === true, // v1.14.5: anything but an explicit true (absent / legacy / corrupt) => OFF
    shuttleEco: {
      costPerTube: Math.max(0, Number(sEco.costPerTube) || 0),
      shuttlesPerTube: Math.max(0, Number(sEco.shuttlesPerTube) || 0),
      sellingPricePerShuttle: Math.max(0, Number(sEco.sellingPricePerShuttle) || 0),
      purchaseRows: sEcoPurchaseRows,
    },
    courtCost: {
      ratePerHour: Math.max(0, Number(cCost.ratePerHour) || 0),
      manualOverrideTotal: cCost.manualOverrideTotal != null && !isNaN(cCostOverrideNum) ? Math.max(0, cCostOverrideNum) : null,
    },
    otherExpenses: (Array.isArray(base.otherExpenses) ? base.otherExpenses : [])
      .filter((it) => it && typeof it === "object")
      .map((it) => ({ id: it.id || uid(), name: String(it.name || ""), amount: Math.max(0, Number(it.amount) || 0) })),
    averageMatchMinutes: amm > 0 ? amm : 15,
    courtUtilization: util > 0 && util <= 1 ? util : 0.9,
    courtRecommendationMode: ["busy", "balanced", "saving"].includes(base.courtRecommendationMode) ? base.courtRecommendationMode : "balanced",
    averageSetMinutes: asm > 0 ? asm : 15,
    courtRecommendationGoal: ["max_wait", "min_games"].includes(base.courtRecommendationGoal) ? base.courtRecommendationGoal : "max_wait",
    maxWaitMinutes: mwm > 0 ? mwm : 30,
    minGamesPerPerson: mgp > 0 ? mgp : 4,
    targetWaitMinutes: twm > 0 ? twm : 15,
    splitExpenses: { court: Number(se.court) || 0, shuttle: Number(se.shuttle) || 0, water: Number(se.water) || 0, other: Number(se.other) || 0 },
    roundingMode: ["none", "round5", "round10"].includes(base.roundingMode) ? base.roundingMode : "none",
    maxPlayers: Number(base.maxPlayers) > 0 ? Number(base.maxPlayers) : null,
    inactiveMonths: Number(base.inactiveMonths) > 0 ? Number(base.inactiveMonths) : 6,
    // v1.11.67: same field-by-field backfill discipline as shuttleEco/courtCost above — a missing/partial
    // membership object (any pre-v1.11.67 backup, or a hand-edited/corrupted import) must never produce
    // NaN pricing or a crash in getMembershipStatus/payMembership.
    membership: {
      entranceFee: {
        enabled: !!(bMembership.entranceFee && bMembership.entranceFee.enabled),
        amount: Math.max(0, Number(bMembership.entranceFee && bMembership.entranceFee.amount) || 0),
      },
      recurring: {
        enabled: !!(bMembership.recurring && bMembership.recurring.enabled),
        monthlyFee: Math.max(0, Number(bMembership.recurring && bMembership.recurring.monthlyFee) || 0),
        annualFee: Math.max(0, Number(bMembership.recurring && bMembership.recurring.annualFee) || 0),
      },
      expiryWarningDays: Number(base.membership && base.membership.expiryWarningDays) > 0 ? Number(base.membership.expiryWarningDays) : 7,
    },
    // v1.12.51 (Promotion & Loyalty Foundation, spec section 1): field-by-field normalization, same
    // discipline as shuttleEco/courtCost/otherExpenses above — a missing field (any pre-v1.12.51 backup) ->
    // [] (no existing group suddenly receives an active promotion after upgrading); a corrupt/partial entry
    // is sanitized rather than allowed to crash a later render.
    promotions: normalizePromotions(base.promotions),
  };
}
// v1.12.51 (Promotion & Loyalty Foundation): one opaque, stable campaignId per campaign; every other field is
// defensively coerced so a hand-edited/corrupted backup can never produce NaN/crash downstream. Unknown
// legacy shapes simply fall back to safe defaults — this is additive normalization, never destructive.
function normalizePromotionCampaign(c) {
  const base = c && typeof c === "object" ? c : {};
  const trig = base.trigger && typeof base.trigger === "object" ? base.trigger : {};
  const rew = base.reward && typeof base.reward === "object" ? base.reward : {};
  const mr = Number(base.maxRewards);
  return {
    campaignId: base.campaignId || uid(),
    name: String(base.name || "").trim(), // user-entered, never auto-translated/altered beyond trimming
    enabled: base.enabled !== false, // default ON for a freshly-created campaign; explicit false only from Pause
    archived: !!base.archived, // spec section 13: soft-delete only, once a campaign has prior awards
    eligibility: ["all", "member", "guest"].includes(base.eligibility) ? base.eligibility : "all",
    trigger: {
      kind: trig.kind === "attendanceStreak" ? "attendanceStreak" : "attendanceCount", // future kinds (registrationOrder/registrationBefore) extend this union only — see promotionFutureTriggerKinds note below
      target: Math.max(1, Math.round(Number(trig.target)) || 1),
    },
    repeatMode: base.repeatMode === "every_target" ? "every_target" : "once",
    startDate: base.startDate || null, // ISO date string ("YYYY-MM-DD") or null = no lower bound
    endDate: base.endDate || null,
    reward: {
      type: ["discount", "physical", "cash"].includes(rew.type) ? rew.type : "physical",
      name: String(rew.name || "").trim(), // user-entered, never auto-translated
      amount: Math.max(0, Number(rew.amount) || 0), // discount ฿ or cash ฿
      displayValue: Math.max(0, Number(rew.displayValue) || 0), // physical reward, member-facing (spec section 9)
      costAmount: Math.max(0, Number(rew.costAmount) || 0), // physical reward, organizer's real cost / Finance expense
    },
    maxRewards: mr > 0 ? Math.round(mr) : null, // null = unlimited
    createdAt: base.createdAt || Date.now(),
  };
}
function normalizePromotions(arr) {
  return (Array.isArray(arr) ? arr : []).filter((c) => c && typeof c === "object").map(normalizePromotionCampaign);
}
// v1.11.34: migrates settings.wheelPrizes into the new reward model — decouples Probability from
// Quantity/Player-count entirely (spec section 6: "จำนวน Player ≠ จำนวน Reward ≠ Probability"). Old saved
// data only ever had {id,label,type,amount,qty,totalQty}; a missing `probability` is derived from the OLD
// implicit odds (every unit of qty was 1 of 2 equal slices — 1 prize + 1 miss — among ALL real prizes'
// units combined, i.e. a flat 50% total win chance split proportionally by qty) so a freshly-upgraded
// wheel keeps behaving THE SAME on the very first spin after upgrading, just now expressed as an explicit
// % instead of an implicit qty ratio. Also drops any old "none" (ไม่ได้รางวัล) row entirely — the new
// architecture always computes "no prize" as the automatic remainder (100 - sum of active probabilities),
// it is no longer a real editable prize (spec 6.2/6.3). Idempotent: already-migrated prizes (probability/
// value/wheelOrder already present) pass through with just their numbers clamped/coerced, so it's safe to
// call on every load, not just once.
function normWheelPrizes(prizes) {
  const real = (Array.isArray(prizes) ? prizes : []).filter((p) => p && p.type !== "none");
  const totalQtyAll = real.reduce((s, p) => s + prizeQty(p), 0);
  return real.map((p, i) => ({
    ...p,
    type: ["now", "next", "item", "cash"].includes(p.type) ? p.type : "item",
    qty: prizeQty(p),
    totalQty: p.totalQty != null ? Math.max(0, Number(p.totalQty) || 0) : prizeQty(p),
    probability: p.probability != null ? Math.max(0, Math.min(100, Number(p.probability) || 0)) : (totalQtyAll > 0 ? Math.round((prizeQty(p) / (2 * totalQtyAll)) * 1000) / 10 : 10),
    value: Number(p.value) || 0,
    wheelOrder: p.wheelOrder != null ? Number(p.wheelOrder) : i,
  }));
}

/* ============ BACKUP / RESTORE ============
   Local-file backup: the exported JSON is a thin envelope (app/backupVersion/schemaVersion/appVersion/
   exportedAt) around a `data` object that is exactly the same shape already persisted to localStorage
   under "bg-v11" — so building a backup is just "wrap the current state", and importing is "validate,
   migrate to the current schema, then feed it through the same setters the app uses on normal load". */
const BACKUP_APP_ID = "BadQ";
const BACKUP_VERSION = 1; // outer envelope format — bump only if this wrapper shape itself changes
const SCHEMA_VERSION = 1; // localGroups is an optional, backward-compatible schema-1 field. Missing values
                          // normalize safely during boot/restore; no incompatible backup contract exists.
// Auto-backup checkpoints (v1.9.16) — a silent, in-app safety net for organizers who never remember to
// tap "สำรองข้อมูล" themselves. Every time a ก๊วน or Tournament finishes, a full snapshot (same envelope
// shape as a manual backup file) is stashed into localStorage under this key — no dialog, no download,
// nothing that could interrupt the "จบก๊วน" flow. Kept as a short rotating list so it can't grow without
// bound; each entry restores through the exact same preview/confirm UI as importing a backup FILE.
const AUTO_BACKUP_KEY = "bg-v11-autobackups";
const AUTO_BACKUP_MAX = 8; // last 8 checkpoints — a few weeks of ก๊วนs for most groups, negligible storage cost
// v1.9.18: a tiny forensic ring buffer for diagnosing the "data reverted after updating" class of bug —
// records every boot (loaded savedAt + player/session counts) and every time the safety guard actually
// pulls in newer data from storage ("heal"), so a reported regression can be traced after the fact
// instead of guessed at. Read-only from the UI (ตั้งค่า → ข้อมูลและการสำรอง); never affects app behavior.
const BOOT_LOG_KEY = "bg-v11-bootlog";
const BOOT_LOG_MAX = 20;
// v1.11.0 PERSISTENCE REWRITE — Last Known Good snapshot: a copy of the most recent state that
// successfully passed boot (or was just saved during a normal, non-recovering session). Sits between
// the live primary/mirror pair and the Auto-Backup list in the recovery hierarchy: cheaper/fresher than
// digging through Auto-Backup (which only updates when a ก๊วน/Tournament archives), but still a
// completely separate key from "bg-v11" so a corrupted primary can never take this down with it. Goes
// through the exact same window.storage (IndexedDB-primary + localStorage-mirror) plumbing as every
// other key here — see BOOT SEQUENCE below for how/when it's read and (re)written.
const LKG_KEY = "bg-v11-lkg";
// v1.12.39 staged-restore keys (see RESTORE CRASH-CONSISTENCY PROTOCOL in App()).
const PRERESTORE_KEY = "bg-v11-prerestore";              // verified pre-restore safety snapshot (undo point)
