      const shuttleOpeningCarryForward = carryForwardShuttleOpeningFor(base.session.name, base.sessionHistory);
      const shuttleOpeningResolved = resolveShuttleOpening(base.session.shuttleOpening, shuttleOpeningCarryForward);
      // v1.11.45 (History attendee filter): same "attended" definition computeBill()/computeSplitExpenseSummary()
