        photoRef: base.session.photoRef || null,
        photo: base.session.photoRef ? null : (base.session.photo || null), // ก๊วน's own photo (distinct from any player's photo) — frozen into history as-is
        endedAt: Date.now(),
        courtCount: base.courtCount, mode: base.mode, // v1.12.36 (P1 #5): base.courtCount, not the outer closure's `courtCount`
        settings: { ...base.settings },
        levelPresetId: base.settings.levelPresetId || "badweb-central", // freeze which preset was active — historical display must never change later
        // v1.11.45 (History attendee filter): freeze only players who ACTUALLY ATTENDED this session (see
